using DotNetArch.Core.Config;
using DotNetArch.Core.Doctor;
using DotNetArch.Core.Hosting;
using DotNetArch.Core.Operations;
using DotNetArch.Core.Tests.Support;
using Xunit;

namespace DotNetArch.Core.Tests;

/// <summary>A service that was not generated by the tool: its shape is read from disk, it gets the persistence skeleton and the tenant standard, and the doctor fixes what it can (R-J14..R-J18).</summary>
public sealed class LegacyServiceTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "dotnet-arch-legacy-" + Guid.NewGuid().ToString("N"));
    private readonly FakeProcessRunner _runner = new();

    public LegacyServiceTests()
    {
        Directory.CreateDirectory(_root);
        Write("Shop.sln", "");
        Write("Directory.Packages.props", "<Project>\n  <ItemGroup>\n    <PackageVersion Include=\"MediatR\" Version=\"12.2.0\" />\n    <PackageVersion Include=\"Microsoft.Extensions.Configuration\" Version=\"9.0.1\" />\n  </ItemGroup>\n\n</Project>\n");
        Directory.CreateDirectory(Path.Combine(_root, "test"));
        Write("src/Shop.Domain/Shop.Domain.csproj", "<Project Sdk=\"Microsoft.NET.Sdk\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup></Project>");
        Write("src/Shop.Application/Shop.Application.csproj", "<Project Sdk=\"Microsoft.NET.Sdk\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup></Project>");
        Write("src/Shop.Infrastructure/Shop.Infrastructure.csproj", "<Project Sdk=\"Microsoft.NET.Sdk\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup></Project>");
        Write("src/Shop.Api/Shop.Api.csproj", "<Project Sdk=\"Microsoft.NET.Sdk.Web\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup></Project>");
        Write("src/Shop.Api/Dockerfile", "FROM mcr.microsoft.com/dotnet/sdk:9.0 AS build\nRUN dotnet publish\n\nFROM mcr.microsoft.com/dotnet/aspnet:9.0 AS final\nEXPOSE 5273\nENTRYPOINT [\"dotnet\", \"Shop.Api.dll\"]\n");
        Write("src/Shop.Api/appsettings.json", "{\n  \"Logging\": {}\n}\n");
        Write("src/Shop.Api/Controllers/OrdersController.cs", "using Microsoft.AspNetCore.Mvc;\n\nnamespace Shop.Api.Controllers;\n\n[ApiController]\npublic sealed class OrdersController : ControllerBase\n{\n}\n");
        Write("src/Shop.Api/Program.cs", "using Microsoft.Extensions.Hosting;\nusing Shop.Application;\n\nvar builder = WebApplication.CreateBuilder(args);\n\nbuilder.Services.AddMediatR(cfg =>\n{\n    cfg.RegisterServicesFromAssembly(typeof(AssemblyMarker).Assembly);\n});\n\nbuilder.Services.AddValidatorsFromAssemblyContaining<AssemblyMarker>();\nbuilder.Services.AddCors(options =>\n{\n    options.AddDefaultPolicy(policy =>\n    {\n        policy.AllowAnyOrigin().AllowAnyHeader();\n    });\n});\n\nvar app = builder.Build();\napp.UseCors();\napp.Run();\n");
        Write("tenancy.profile.yml", "name: tenancy\nversion: 1.1.0\nexternal_kits:\n  - area: Tenancy\n    packages:\n      - { id: Corevia.Kit.Tenancy.Abstractions, version: 1.1.0, projects: [application] }\n      - { id: Corevia.Kit.Tenancy.Core, version: 1.1.0, projects: [api] }\n    hosts:\n      api: { usings: [Corevia.Kit.Tenancy], builder: [\"builder.Services.AddCoreviaTenancy(builder.Configuration);\"] }\n");
    }

    public void Dispose() => Directory.Delete(_root, recursive: true);

    private void Write(string relative, string content)
    {
        var path = Path.Combine(_root, relative);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
    }

    private string Read(string relative) => File.ReadAllText(Path.Combine(_root, relative));

    private OperationResult Run(string name, bool apply, params (string Key, string Value)[] extra)
    {
        using var _ = ToolHost.Use(new HostContext(new NonInteractivePrompter(), new BufferedToolOutput(), _runner));
        var values = new Dictionary<string, string> { ["path"] = _root };
        foreach (var (key, value) in extra)
            values[key] = value;
        return OperationRegistry.Execute(OperationRegistry.Find(name)!, values, apply);
    }

    private void WriteContext()
    {
        Write("src/Shop.Domain/Entities/Order.cs", "namespace Shop.Domain.Entities;\n\npublic sealed class Order\n{\n    public Guid Id { get; set; }\n}\n");
        Write("src/Shop.Domain/Entities/Line.cs", "namespace Shop.Domain.Entities;\n\npublic class Line : Base\n{\n    public Guid Id { get; set; }\n}\n\npublic class Base\n{\n}\n");
        Write("src/Shop.Infrastructure/Context/ShopDbContext.cs", "using Microsoft.EntityFrameworkCore;\nusing Shop.Domain.Entities;\n\nnamespace Shop.Infrastructure.Context;\n\npublic sealed class ShopDbContext : DbContext\n{\n    public ShopDbContext(DbContextOptions<ShopDbContext> options)\n        : base(options)\n    {\n    }\n\n    public DbSet<Order> Orders => Set<Order>();\n\n    protected override void OnModelCreating(ModelBuilder modelBuilder)\n    {\n        base.OnModelCreating(modelBuilder);\n    }\n}\n");
    }

    // ---- DA-G01: the shape of the service comes from disk ----

    [Fact]
    public void The_shape_of_an_adopted_service_is_read_from_the_solution_the_api_project_and_the_dockerfile()
    {
        var config = ConfigDeriver.Derive(_root)!;

        Assert.Equal("Shop", config.SolutionName);
        Assert.Equal("Shop.Api", config.StartupProject);
        Assert.Equal("v3", config.Layout);
        Assert.Equal("5273", config.ApiPort);
        Assert.Equal("controller", config.ApiStyle);
        Assert.Equal("net9.0", config.TargetFramework);
        Assert.False(config.McpEnabled);
    }

    [Fact]
    public void The_doctor_asks_for_dotnet_arch_yml_and_fix_writes_it()
    {
        Assert.Contains(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-G01");

        var fix = Run("fix", apply: true, ("rules", "DA-G01"));

        Assert.True(fix.Ok);
        Assert.Equal("Shop", ConfigManager.Load(_root)!.SolutionName);
        Assert.DoesNotContain(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-G01");
    }

    // ---- DA-K04 / DA-D03 / DA-M09 ----

    [Fact]
    public void Fix_lists_the_origins_of_the_configuration_instead_of_any_origin()
    {
        Assert.Contains(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-K04");

        Run("fix", apply: true, ("rules", "DA-K04"));

        Assert.Contains("WithOrigins(builder.Configuration.GetSection(\"Cors:AllowedOrigins\")", Read("src/Shop.Api/Program.cs"), StringComparison.Ordinal);
        Assert.DoesNotContain("AllowAnyOrigin", Read("src/Shop.Api/Program.cs"), StringComparison.Ordinal);
        Assert.Contains("AllowedOrigins", Read("src/Shop.Api/appsettings.json"), StringComparison.Ordinal);
        Assert.DoesNotContain(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-K04");
    }

    [Fact]
    public void Fix_writes_an_openapi_snapshot_test_over_the_controllers_when_the_tests_have_no_application_host()
    {
        Write("test/Shop.Api.Tests/Shop.Api.Tests.csproj", "<Project Sdk=\"Microsoft.NET.Sdk\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup></Project>");
        Write("src/Shop.Api/Shop.Api.csproj", "<Project Sdk=\"Microsoft.NET.Sdk.Web\"><PropertyGroup><TargetFramework>net9.0</TargetFramework></PropertyGroup><ItemGroup><PackageReference Include=\"Swashbuckle.AspNetCore\" /></ItemGroup></Project>");
        Assert.Contains(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-M09");

        var fix = Run("fix", apply: true, ("rules", "DA-M09"));

        Assert.True(fix.Ok, fix.Text);
        var test = Read("test/Shop.Api.Tests/OpenApiSnapshotTests.cs");
        Assert.Contains("typeof(OrdersController)", test, StringComparison.Ordinal);
        Assert.Contains("using Shop.Api.Controllers;", test, StringComparison.Ordinal);
        Assert.Contains("using Xunit;", test, StringComparison.Ordinal);
    }

    // ---- add_tenancy ----

    [Fact]
    public void Add_tenancy_wires_the_kit_scopes_every_entity_and_filters_the_context_and_repeating_changes_nothing()
    {
        WriteContext();
        var profile = Path.Combine(_root, "tenancy.profile.yml");

        var plan = Run("add_tenancy", apply: false, ("profile", profile));
        Assert.True(plan.Ok, plan.Text);
        Assert.False(plan.Applied);
        Assert.DoesNotContain("ITenantOwned", Read("src/Shop.Domain/Entities/Order.cs"), StringComparison.Ordinal);

        var applied = Run("add_tenancy", apply: true, ("profile", profile));
        Assert.True(applied.Ok, applied.Text);

        Assert.Contains("public sealed class Order : ITenantOwned", Read("src/Shop.Domain/Entities/Order.cs"), StringComparison.Ordinal);
        Assert.Contains("public string TenantId { get; set; } = string.Empty;", Read("src/Shop.Domain/Entities/Order.cs"), StringComparison.Ordinal);
        Assert.Contains("public interface ITenantOwned", Read("src/Shop.Domain/Tenancy/ITenantOwned.cs"), StringComparison.Ordinal);
        var context = Read("src/Shop.Infrastructure/Context/ShopDbContext.cs");
        Assert.Contains("ICallerContext? caller = null", context, StringComparison.Ordinal);
        Assert.Contains("HasQueryFilter(e => CurrentTenantId == null || e.TenantId == CurrentTenantId)", context, StringComparison.Ordinal);
        Assert.Contains("StampTenant();", context, StringComparison.Ordinal);
        Assert.Contains("ApplyTenancy(modelBuilder);", context, StringComparison.Ordinal);
        Assert.Contains("builder.Services.AddCoreviaTenancy(builder.Configuration);", Read("src/Shop.Api/Program.cs"), StringComparison.Ordinal);
        Assert.Contains("using Corevia.Kit.Tenancy;", Read("src/Shop.Api/Program.cs"), StringComparison.Ordinal);
        Assert.Contains("Corevia.Kit.Tenancy.Core", Read("src/Shop.Api/Shop.Api.csproj") + Read("Directory.Packages.props"), StringComparison.Ordinal);

        var again = Run("add_tenancy", apply: false, ("profile", profile));
        Assert.Empty(again.Plan ?? Array.Empty<PlannedChange>());
    }

    [Fact]
    public void Add_tenancy_lists_what_it_cannot_patch_by_text_and_refuses_a_profile_without_the_kit()
    {
        WriteContext();
        Write("src/Shop.Infrastructure/Context/ShopDbContext.cs", Read("src/Shop.Infrastructure/Context/ShopDbContext.cs").Replace("    public DbSet", "    public override int SaveChanges() => base.SaveChanges();\n\n    public DbSet", StringComparison.Ordinal));
        Write("other.profile.yml", "name: other\nversion: 1.0.0\nexternal_kits: []\n");

        var result = Run("add_tenancy", apply: true, ("profile", Path.Combine(_root, "tenancy.profile.yml")));
        Assert.Contains("manual:", result.Text, StringComparison.Ordinal);
        Assert.DoesNotContain("ApplyTenancy(", Read("src/Shop.Infrastructure/Context/ShopDbContext.cs"), StringComparison.Ordinal);

        var refused = Run("add_tenancy", apply: false, ("profile", Path.Combine(_root, "other.profile.yml")));
        Assert.False(refused.Ok);
    }

    [Fact]
    public void The_tenancy_standard_is_opt_in_and_the_doctor_names_the_entities_that_belong_to_no_tenant()
    {
        WriteContext();
        Assert.DoesNotContain(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-TN01");

        Write(".net-arch/project.yml", "schema: 2\nblueprint: 1.0.0\nlayout: v3\nstandards:\n- tenancy\n");
        var finding = DoctorRunner.Run(_root).Findings.Single(f => f.Id == "DA-TN01");
        Assert.Contains("Order", finding.Details!);

        var fix = Run("fix", apply: true, ("rules", "DA-TN01"), ("tenancy_profile", Path.Combine(_root, "tenancy.profile.yml")));
        Assert.True(fix.Ok, fix.Text);
        Assert.DoesNotContain(DoctorRunner.Run(_root).Findings, f => f.Id == "DA-TN01");
    }

    // ---- add_persistence ----

    [Fact]
    public void Add_persistence_gives_a_service_without_a_database_the_standard_skeleton_once()
    {
        var plan = Run("add_persistence", apply: false);
        Assert.True(plan.Ok, plan.Text);
        Assert.False(File.Exists(Path.Combine(_root, "src/Shop.Application/Abstractions/Persistence/IUnitOfWork.cs")));

        var applied = Run("add_persistence", apply: true);
        Assert.True(applied.Ok, applied.Text);

        Assert.True(File.Exists(Path.Combine(_root, "src/Shop.Application/Abstractions/Persistence/IUnitOfWork.cs")));
        Assert.True(File.Exists(Path.Combine(_root, "src/Shop.Domain/Common/Entity.cs")));
        Assert.True(File.Exists(Path.Combine(_root, "src/Shop.Infrastructure/Persistence/AppDbContext.cs")));
        var program = Read("src/Shop.Api/Program.cs");
        Assert.Contains("builder.Services.AddApplication();", program, StringComparison.Ordinal);
        Assert.Contains("builder.Services.AddInfrastructure(builder.Configuration);", program, StringComparison.Ordinal);
        Assert.Contains("await app.Services.InitializeInfrastructureAsync();", program, StringComparison.Ordinal);
        Assert.DoesNotContain("AddMediatR", program, StringComparison.Ordinal);
        var props = Read("Directory.Packages.props");
        Assert.Contains("Microsoft.EntityFrameworkCore\"", props, StringComparison.Ordinal);
        Assert.Contains("Npgsql.EntityFrameworkCore.PostgreSQL", props, StringComparison.Ordinal);
        Assert.DoesNotContain("Version=\"9.0.1\"", props, StringComparison.Ordinal);
        Assert.Contains("Microsoft.EntityFrameworkCore", Read("src/Shop.Infrastructure/Shop.Infrastructure.csproj"), StringComparison.Ordinal);
        Assert.Equal("Postgres", ConfigManager.Load(_root)!.DatabaseProvider);

        Assert.Empty(Run("add_persistence", apply: false).Plan ?? Array.Empty<PlannedChange>());
    }

    [Fact]
    public void Add_persistence_never_overwrites_a_file_and_refuses_a_service_that_has_an_ef_context()
    {
        Write("src/Shop.Domain/Common/Entity.cs", "// mine");
        Run("add_persistence", apply: true);
        Assert.Equal("// mine", Read("src/Shop.Domain/Common/Entity.cs"));

        WriteContext();
        var refused = Run("add_persistence", apply: false);
        Assert.False(refused.Ok);
        Assert.Contains("already has an EF context", refused.Error ?? refused.Text, StringComparison.Ordinal);
    }
}
